import { describe, test, expect } from 'vitest';
import { ZimmInlineMessage } from './zimmInlineMessage.css';

/**
 * Recipe wiring — SFCC-795 §11.2 pass criteria 2 and 6. Reads the exported recipe object
 * directly so these assert the real resolved token references, not a rendered component's
 * computed style (jsdom does not reliably resolve custom-property values) and not a hardcoded
 * hex duplicate of the foundation source.
 *
 * SFCC-795 rework: the recipe moved from a single-node `defineStyleConfig` to a two-part
 * (`root`/`text`) plain-object recipe (see zimmInlineMessage.css.ts's own docblock) — every
 * property path below was updated to read through the owning part; the underlying claim each
 * test makes (status-error/text-muted tokens not hardcoded hex, regular-weight override, full
 * width, exactly two variants) is unchanged.
 */
describe('ZimmInlineMessage — recipe wiring', () => {
  test('error variant resolves to the real status-error colour token var, not a hardcoded hex', () => {
    // No `!`/`as` here (unlike baseStyle below): now that this recipe is a plain object literal
    // (SFCC-795 rework, no more `defineStyleConfig` wrapper), TypeScript infers `variants` and its
    // two keys precisely enough on their own that ESLint's no-unnecessary-type-assertion rule
    // flags both as redundant — confirmed by running lint, not assumed.
    const error = ZimmInlineMessage.variants.error;
    expect(error.root.color).toBe('var(--zimm-color-status-error)');
    expect(error.root.color).not.toMatch(/#/);
  });

  test('warning variant resolves to the real muted-text colour token var, not a hardcoded hex', () => {
    const warning = ZimmInlineMessage.variants.warning;
    expect(warning.root.color).toBe('var(--zimm-color-text-muted)');
    expect(warning.root.color).not.toMatch(/#/);
  });

  test('no low-stock (or any third) variant exists in the recipe', () => {
    expect(Object.keys(ZimmInlineMessage.variants).sort()).toEqual(['error', 'warning']);
  });

  test('caption textStyle is overridden to regular weight, not left at its medium default', () => {
    const base = ZimmInlineMessage.baseStyle as { text: Record<string, unknown> };
    expect(base.text.textStyle).toBe('caption');
    expect(base.text.fontWeight).toBe('var(--zimm-font-weight-regular)');
  });

  test('spans the full row width, matching the Figma "w-full" annotation', () => {
    const base = ZimmInlineMessage.baseStyle as { root: Record<string, unknown> };
    expect(base.root.width).toBe('full');
  });

  // SFCC-795 rework: declares exactly the two parts the component actually reads —
  // recipeParts.test.ts reconciles this against index.tsx's own `styles.root`/`styles.text`
  // reads. No separate `icon` part — see zimmInlineMessage.css.ts's own docblock for why.
  test('declares exactly the root and text parts, no more, no less', () => {
    expect(ZimmInlineMessage.parts).toEqual(['root', 'text']);
  });
});

